package com.aistock.prediction.portfolioquestion;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import com.fasterxml.jackson.databind.*;import com.aistock.common.BusinessException;import com.aistock.prediction.maas.MaasOperationGate;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;import java.util.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static com.aistock.prediction.portfolioquestion.QuestionEvidence.*;import static com.aistock.prediction.portfolioquestion.PortfolioQuestionRecords.*;
@Tag("mysql") class PortfolioQuestionRepositoryTest {
 JdbcTemplate jdbc;PortfolioQuestionRepository repo;static final Instant NOW=Instant.parse("2026-10-20T00:00:00Z");Clock clock=Clock.fixed(NOW,ZoneOffset.UTC);
 @BeforeEach void setup(){String u=System.getenv("PREDICTION_TEST_DB_URL"),p=System.getenv("PREDICTION_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_prediction_test?serverTimezone=UTC".equals(u)||p==null||p.isBlank())throw new IllegalStateException("Only isolated prediction database allowed");jdbc=new JdbcTemplate(new DriverManagerDataSource(u,"root",p));assertEquals("stock_prediction_test",jdbc.queryForObject("select database()",String.class));Flyway.configure().dataSource(jdbc.getDataSource()).locations("classpath:db/migration").load().migrate();clean();jdbc.update("delete from portfolio_market_use");jdbc.update("delete from portfolio_analysis_operation");jdbc.update("delete from portfolio_analysis_result");jdbc.update("insert into portfolio_analysis_result(analysis_id,owner_id,snapshot_json,quotes_json,result_json,source_hash,created_at) values(?,?,'{}','{}',?,?,?)",ID.toString(),OWNER.toString(),saved().toString(),"a".repeat(64),java.sql.Timestamp.from(NOW));repo=new PortfolioQuestionRepository(jdbc,M);}
 void clean(){jdbc.update("update prediction_explanation_slot set operation_id=null,lease_until=null,operation_kind=null where slot_id=1");jdbc.update("delete from portfolio_question_operation");jdbc.update("delete from portfolio_question_result");}
 @AfterEach void after(){if(jdbc!=null)clean();}
 Request request(String q){return new Request(UUID.randomUUID(),ID,q,true);}Facts facts(String q){return PortfolioQuestionFacts.build(saved(),q,"m",M);}Answer answer(){var a=M.createArrayNode();a.addObject().put("text","合成已核验回答").putArray("refs").add("AS_OF");return new Answer("ANSWERED","COVERAGE",a);}
 @Test void storesOwnedAnswerReplaysAndCachesWithoutCallingAgain(){var req=request("解释");assertTrue(repo.claim(OWNER,req,facts(req.question()),clock).execute());var done=repo.complete(OWNER,req.operationId(),answer(),null,clock);assertEquals("SUCCEEDED",done.state());assertEquals(done,repo.replay(OWNER,req,clock));assertFalse(repo.claim(OWNER,req,facts(req.question()),clock).execute());assertEquals("ANSWERED",repo.get(OWNER,done.answerId()).path("status").asText());var cached=repo.claim(OWNER,request("解释"),facts("解释"),clock);assertFalse(cached.execute());assertEquals(done.answerId(),cached.receipt().answerId());assertNull(jdbc.queryForObject("select operation_id from prediction_explanation_slot where slot_id=1",String.class));}
 @Test void ownerAndParameterBoundariesNeverLeakRecords(){var req=request("解释");repo.claim(OWNER,req,facts("解释"),clock);assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->repo.operation(UUID.randomUUID(),req.operationId(),clock)).code());assertEquals("AI_REQUEST_CONFLICT",assertThrows(BusinessException.class,()->repo.replay(OWNER,new Request(req.operationId(),ID,"另一问题",true),clock)).code());assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->repo.replay(UUID.randomUUID(),req,clock)).code());}
 @Test void failedAndExpiredOriginalOperationsNeverExecuteAgain(){var req=request("解释");repo.claim(OWNER,req,facts("解释"),clock);var failed=repo.complete(OWNER,req.operationId(),null,"AI_OUTPUT_INVALID",clock);assertEquals("FAILED",failed.state());assertFalse(repo.claim(OWNER,req,facts("解释"),clock).execute());var next=request("解释");assertTrue(repo.claim(OWNER,next,facts("解释"),clock).execute());assertEquals("FAILED",repo.operation(OWNER,next.operationId(),Clock.fixed(NOW.plusSeconds(46),ZoneOffset.UTC)).state());assertEquals(0,jdbc.queryForObject("select count(*) from portfolio_question_result",Integer.class));}
 @Test void concurrentSameOperationHasOneExecutor()throws Exception{var req=request("解释");var e=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);var a=e.submit(()->{start.await();return repo.claim(OWNER,req,facts("解释"),clock);});var b=e.submit(()->{start.await();return repo.claim(OWNER,req,facts("解释"),clock);});start.countDown();assertEquals(1,(a.get(5,TimeUnit.SECONDS).execute()?1:0)+(b.get(5,TimeUnit.SECONDS).execute()?1:0));}finally{e.shutdownNow();}}
 @Test void allExistingPaidKindsShareTheSameSlot(){var gate=new MaasOperationGate(jdbc);for(String kind:List.of("PREDICTION_EXPLANATION","STOCK_ANALYSIS","STOCK_QUESTION","COMPARISON_EXPLANATION")){var other=UUID.randomUUID();gate.lockAndAcquire(kind,other,NOW);var req=request("解释");assertEquals("AI_BUSY",assertThrows(BusinessException.class,()->repo.claim(OWNER,req,facts("解释"),clock)).code());assertEquals(other.toString(),jdbc.queryForObject("select operation_id from prediction_explanation_slot where slot_id=1",String.class));gate.release(kind,other);}assertEquals(0,jdbc.queryForObject("select count(*) from portfolio_question_operation",Integer.class));}
 @Test void lockWaitCrossingDeadlineNeverWritesLateAnswer()throws Exception{for(int seconds:new int[]{46,51}){clean();var req=request("解释");repo.claim(OWNER,req,facts("解释"),clock);var current=new AtomicReference<>(NOW);var c=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return current.get();}};var e=Executors.newSingleThreadExecutor();try(var lock=jdbc.getDataSource().getConnection()){lock.setAutoCommit(false);try(var stmt=lock.prepareStatement("select slot_id from prediction_explanation_slot where slot_id=1 for update")){stmt.executeQuery().close();}var result=e.submit(()->repo.complete(OWNER,req.operationId(),answer(),null,c));long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);boolean waited=false;while(System.nanoTime()<end){if(jdbc.queryForObject("select count(*) from performance_schema.data_lock_waits",Integer.class)>0){waited=true;break;}Thread.sleep(10);}assertTrue(waited);current.set(NOW.plusSeconds(seconds));lock.commit();assertEquals("FAILED",result.get(4,TimeUnit.SECONDS).state());assertEquals(0,jdbc.queryForObject("select count(*) from portfolio_question_result",Integer.class));}finally{e.shutdownNow();}}}
 @Test void fixedUpperHistoryDoesNotIncludeNewerAnswers(){for(int i=0;i<12;i++){var req=request("问题"+i);repo.claim(OWNER,req,facts(req.question()),clock);repo.complete(OWNER,req.operationId(),answer(),null,clock);}var page=repo.list(OWNER,ID,null,null,true,clock);assertEquals(10,page.items().size());assertNotNull(page.nextBefore());var req=request("新的");repo.claim(OWNER,req,facts("新的"),clock);repo.complete(OWNER,req.operationId(),answer(),null,clock);var older=repo.list(OWNER,ID,page.nextBefore(),page.upper(),true,clock);assertEquals(2,older.items().size());assertEquals(page.upper(),older.upper());}
 @Test void oversizedAnswerRollbackLeavesNoOrphan(){var req=request("解释");repo.claim(OWNER,req,facts("解释"),clock);var huge=M.createArrayNode().add("x".repeat(17000));assertThrows(BusinessException.class,()->repo.complete(OWNER,req.operationId(),new Answer("ANSWERED","COVERAGE",huge),null,clock));assertEquals(0,jdbc.queryForObject("select count(*) from portfolio_question_result",Integer.class));assertEquals("RUNNING",repo.operation(OWNER,req.operationId(),clock).state());}
 @Test void anotherOperationCannotCompleteOrReleaseCurrentSlot(){var a=request("A");repo.claim(OWNER,a,facts("A"),clock);repo.operation(OWNER,a.operationId(),Clock.fixed(NOW.plusSeconds(46),ZoneOffset.UTC));var b=request("B");repo.claim(OWNER,b,facts("B"),Clock.fixed(NOW.plusSeconds(46),ZoneOffset.UTC));assertEquals("FAILED",repo.complete(OWNER,a.operationId(),answer(),null,Clock.fixed(NOW.plusSeconds(47),ZoneOffset.UTC)).state());assertEquals(b.operationId().toString(),jdbc.queryForObject("select operation_id from prediction_explanation_slot where slot_id=1",String.class));}
 @Test void finalOperationWriteFailureRollsBackInsertedAnswer(){var req=request("解释");repo.claim(OWNER,req,facts("解释"),clock);jdbc.execute("create trigger portfolio_question_fixture_reject before update on portfolio_question_operation for each row SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic fixture rejection'");try{assertThrows(RuntimeException.class,()->repo.complete(OWNER,req.operationId(),answer(),null,clock));assertEquals(0,jdbc.queryForObject("select count(*) from portfolio_question_result",Integer.class));assertEquals("RUNNING",jdbc.queryForObject("select state from portfolio_question_operation where operation_id=?",String.class,req.operationId().toString()));}finally{jdbc.execute("drop trigger portfolio_question_fixture_reject");}}
}
